import{z as s,x as o,o as e,c as p,q as l,j as i,D as E,d as t,s as A,S as n,b as B}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"Multi-Raft","description":"","frontmatter":{"title":"Multi-Raft","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/con-multi-raft.md","filePath":"cs/con-multi-raft.md","lastUpdated":1791413859000}'),d={name:"cs/con-multi-raft.md"};function f(P,a,u,m,c,C){const r=o("Mermaid");return e(),p("div",null,[a[2]||(a[2]=l('<h1 id="multi-raft" tabindex="-1">Multi-Raft <a class="header-anchor" href="#multi-raft" aria-label="Permalink to &quot;Multi-Raft&quot;">​</a></h1><div class="epigraph"><p>单组共识的难题是一份日志怎么活下来；切成几千组之后，难题变成几千份日志怎么不打架——协议没有变难，秩序变贵了。</p><footer>—— 据 Corbett et al., Spanner, OSDI 2012 与 Huang et al., TiDB, VLDB 2020 整理</footer></div><p><a href="/cs/con-raft-implementation">上一课</a>把单组 Raft 的实现账单列全：落盘次序、选举与回退、三档读。缺口是容量与放置：一个领导者、一份多数派撑不起大数据量，也回答不了「数据住哪个机架」。本课写 Multi-Raft——按分片把共识复制几千份，以及切组之后冒出来的新账：分裂合并、副本迁移、心跳聚合，以及跨组一致性为什么必须回到 2PC。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单组 Raft 有三个结构性极限。吞吐：所有写挤过一个领导者的日志，多数派 fsync 是全局串行点。容量：状态机与日志都在同一台机器上，存不下就无解。放置：副本落在哪里由初始部署定死，搬不动。切组同时解三件事：把键空间按 range 或 hash 切成分片，每片一个独立的共识组，各组分摊写入、各占各的盘、各自的副本摆不同拓扑。但切组引入了单组没有的问题：分片边界不是静态的——数据会长大会变热；几千组的选举、心跳、快照同时跑，常驻开销线性放大；更要紧的是，跨组的写没有任何顺序保证——共识只在组内给全序，两个组之间没有共同的时间线，这正是<a href="/cs/consensus-vs-2pc">共识与 2PC</a> 分清过的界：共识卖高可用与组内顺序，跨组原子性要另买。</p><p><span class="marginnote">直觉类比：单组 Raft 像只有一间会议室的总公司——所有审批挤同一张桌；Multi-Raft 是拆成连锁店，每家分店自治表决（组内共识），总部只维护分店名录（路由表）。跨分店的联合活动没人天然担保，得专门请协调人——2PC 就是那个角色。</span></p><h3 id="切、并、搬" tabindex="-1">切、并、搬 <a class="header-anchor" href="#切、并、搬" aria-label="Permalink to &quot;切、并、搬&quot;">​</a></h3><p>分裂：分片超过阈值就从中点切成两个子分片，各自开新组写后续日志。合并是逆操作。迁移：把过热分片的领导者或副本搬到空闲节点，服务跟着走。三件事共享同一条纪律：任何时刻多数派不能有缺口——迁移用 learner 先追平再转正，合并前后两个组各完成各自的配置变更。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>生产系统的分片粒度是百 MiB 量级：TiKV 的 region 默认 96 MiB 触发分裂、144 MiB 是上限。路由表回答「key 在哪个组」，它自身要强一致且高可用，于是放进另一份小共识（根组或元数据服务），形成两级定位：key 到 range，range 到组。均衡器按各组 QPS、磁盘水位、领导者数量做调度：领导者迁移只换服务不搬数据，副本迁移才动盘。心跳是隐性大头：几千组共用少量连接，心跳与消息批量打包，否则每组每秒数次的 RPC 会吃光连接数与 CPU。</p><p><span class="marginnote">数字实例：5000 个组若各自每秒发 3 次心跳 RPC，就是每秒 1.5 万个请求的常驻底噪；把几百条心跳打包进一个消息后，连接数与 CPU 开销都降一个量级。这就是「心跳是隐性大头」的具体含义。</span></p><p><span class="marginnote">一个容易被低估的成本：每组独立的任期与快照意味着监控维度从一份日志变成几十万份——「集群健康」必须聚合成组间分位数，盯单组告警在 Multi-Raft 里没有意义。</span></p>',12)),(e(),i(n,null,{default:E(()=>[A(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEY%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E8%AF%B7%E6%B1%82%20key%22%5D%20--%3E%20ROUTE%5B%22%E8%B7%AF%E7%94%B1%E8%A1%A8%EF%BC%9Akey%20%E5%88%B0%20range%20%E5%88%B0%E7%BB%84%22%5D%0A%20%20ROUTE%20--%3E%20SINGLE%7B%22%E6%98%AF%E5%90%A6%E8%B7%A8%E7%BB%84%EF%BC%9F%22%7D%0A%20%20SINGLE%20--%3E%7C%E5%90%A6%7C%20GRP%5B%22%E7%BB%84%E5%86%85%20Raft%20%E5%86%99%EF%BC%9A%E5%A4%9A%E6%95%B0%E6%B4%BE%E6%97%A5%E5%BF%97%22%5D%0A%20%20SINGLE%20--%3E%7C%E6%98%AF%7C%20TWO%5B%222PC%20%E5%8D%8F%E8%B0%83%E5%90%84%E5%8F%82%E4%B8%8E%E8%80%85%E7%BB%84%22%5D%0A%20%20GRP%20--%3E%20APPLY%5B%22%E7%8A%B6%E6%80%81%E6%9C%BA%E5%BA%94%E7%94%A8%22%5D%0A%20%20TWO%20--%3E%20APPLY%0A%20%20BAL%5B%22%E5%9D%87%E8%A1%A1%E5%99%A8%EF%BC%9AQPS%20%E4%B8%8E%E7%A3%81%E7%9B%98%E4%B8%8E%E9%A2%86%E5%AF%BC%E8%80%85%E6%95%B0%22%5D%20--%3E%20MOVE%5B%22learner%20%E8%BF%BD%E5%B9%B3%E5%90%8E%E8%BD%AC%E6%AD%A3%E8%BF%81%E7%A7%BB%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[t("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"为什么跨组必须回到 2PC：一条事务触碰分片 A 与 B，两组的多数派只能各自承诺组内顺序，谁也不能替对方担保提交；协调者用两阶段问一遍，参与者把「准备提交」写进各自日志——日志有共识兜底，协调者崩溃后参与者仍能凭日志推进。这是主干 2PC 的阻塞问题加上共识之后的工程解，Spanner 的 Paxos 组与 TiKV 的 raftstore 都走这条路。选举风暴是 Multi-Raft 特有的账：网络抖动让几百个组同时超时重选，重选的 CPU 尖峰又拖慢幸存组；随机化各组选举相位、批量发心跳，把它压住。数量级：百 TB 数据按百 MiB 切就是百万级分片，万级到百万级组在这类系统里是常态而非特例。",-1)),(e(),i(n,null,{default:E(()=>[A(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20TX%5B%22%E4%BA%8B%E5%8A%A1%E8%A7%A6%E7%A2%B0%E5%88%86%E7%89%87%20A%20%E4%B8%8E%20B%22%5D%20--%3E%20PREP%5B%22%E5%8D%8F%E8%B0%83%E8%80%85%E5%8F%91%20prepare%22%5D%0A%20%20PREP%20--%3E%20PA%5B%22%E7%BB%84%20A%3A%20%E5%87%86%E5%A4%87%E8%AE%B0%E5%BD%95%E5%86%99%E8%BF%9B%E6%97%A5%E5%BF%97%22%5D%0A%20%20PREP%20--%3E%20PB%5B%22%E7%BB%84%20B%3A%20%E5%87%86%E5%A4%87%E8%AE%B0%E5%BD%95%E5%86%99%E8%BF%9B%E6%97%A5%E5%BF%97%22%5D%0A%20%20PA%20--%3E%20ALL%7B%22%E4%B8%A4%E7%BB%84%E9%83%BD%E5%B0%B1%E7%BB%AA%E4%BA%86%E5%90%97%22%7D%0A%20%20PB%20--%3E%20ALL%0A%20%20ALL%20--%3E%7C%22%E6%98%AF%22%7C%20CMT%5B%22%E5%8F%91%20commit%2C%20%E4%B8%A4%E7%BB%84%E4%B8%80%E8%B5%B7%E7%94%9F%E6%95%88%22%5D%0A%20%20ALL%20--%3E%7C%22%E5%8D%8F%E8%B0%83%E8%80%85%E5%B4%A9%E6%BA%83%22%7C%20REC%5B%22%E5%8F%82%E4%B8%8E%E8%80%85%E5%87%AD%E5%90%84%E8%87%AA%E6%97%A5%E5%BF%97%E6%8E%A8%E8%BF%9B%2C%20%E4%B8%8D%E6%82%AC%E7%A9%BA%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">常见误区：初学者容易以为共识引擎给了「整个集群的全序」。实际上每个组的 Raft 只保证组内日志全序；组与组之间没有共同时间线——A 组排好的一条写与 B 组排好的一条写，谁先谁后无从谈起。跨组要顺序，只能另买 2PC 或外部时间戳（如 Spanner 的 TrueTime）。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不选分片键、不谈哈希与 range 分桶的通识；placement rules 与跨城副本的语义在地理复制课，不在这里展开。共识协议本身一行没改——每组仍是上一课那份账单，改动全在编排层。也别把 Multi-Raft 当分片的唯一姿势：Spanner 用 Paxos 组，链式复制有另一路变体，谱系对照留给下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>切组同时解吞吐、容量、放置；每组仍是完整的单组共识，新账全在编排层。</li><li>分裂、合并、迁移都围绕「多数派不缺口」：learner 追平再转正。</li><li>路由表自身要一份共识；两级定位是这类系统的固定结构。</li><li>跨组原子性必须买 2PC；共识只卖组内顺序，不卖跨组时间线。</li><li>心跳批量与随机相位压选举风暴；监控按组分位数聚合。</li><li>出处：Corbett et al., Spanner, OSDI 2012；Huang et al., TiDB, VLDB 2020；TiKV 文档的分片参数。</li></ul>',5))])}const T=s(d,[["render",f]]);export{h as __pageData,T as default};
